#!/usr/bin/env bash
# Generated by evals/generate.py: edit that, not this file.
#
# The orders project with its history, the hotspots bin/hotspots found in
# it, and the files the case needs, as /vibes:survey leaves them.

set -euo pipefail
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
here="$(cd "$(dirname -- "$0")" && pwd)"
fixtures="${here}/../fixtures"
commit() {
  git add -A
  git -c user.name=evals -c user.email=evals@example.invalid \
    commit -q -m "$1"
}
git init -q -b main .
cp -R "${fixtures}/survey-project/." .
mkdir -p .vibes
printf '*\n' > .vibes/.gitignore
commit "Price and store orders"
while IFS='|' read -r message paths; do
  for path in ${paths}; do printf '# %s\n' "${message}" >> "${path}"; done
  commit "${message}"
done < "${fixtures}/survey-history.txt"
mkdir -p .vibes/survey-eval/designs
"${here}/../../bin/hotspots" > .vibes/survey-eval/hotspots.txt
cp "${fixtures}/retro-tools/tree-check" .vibes/survey-eval/
chmod +x .vibes/survey-eval/tree-check
.vibes/survey-eval/tree-check >/dev/null
mv .vibes/survey-eval/tree-now .vibes/survey-eval/tree-before
